UPDATE places SET name_english=place_name,state_name=(SELECT s.state_name FROM cities c JOIN states s ON s.id=c.state_id WHERE c.id=places.city_id),created_at='2026-10-02',updated_at='2026-10-02',verification_status='partial',verification_notes='Identity/source checked; live/provider metadata not fetched.',verified_at='2026-10-02' WHERE id BETWEEN 807000001 AND 807000092;
UPDATE places SET source=CASE city_id WHEN 8070001 THEN 'Agency for Promotion and Support of Tourism of North Macedonia (tourismmacedonia.gov.mk); Visit Macedonia Skopje city guide (visitmacedonia.mk); checked 2026-10-02' WHEN 8070002 THEN 'Agency for Promotion and Support of Tourism of North Macedonia; Visit Macedonia Ohrid city/lake guides; UNESCO heritage context; checked 2026-10-02' WHEN 8070003 THEN 'Agency for Promotion and Support of Tourism of North Macedonia; Visit Macedonia Bitola city guide; checked 2026-10-02' WHEN 8070004 THEN 'Agency for Promotion and Support of Tourism of North Macedonia; Visit Macedonia Prilep city guide; checked 2026-10-02' WHEN 8070005 THEN 'Agency for Promotion and Support of Tourism of North Macedonia; Visit Macedonia Kruševo city guide; checked 2026-10-02' WHEN 8070006 THEN 'Agency for Promotion and Support of Tourism of North Macedonia; Visit Macedonia Tetovo city guide; checked 2026-10-02' WHEN 8070007 THEN 'Agency for Promotion and Support of Tourism of North Macedonia; Visit Macedonia Kratovo city guide; checked 2026-10-02' WHEN 8070008 THEN 'Agency for Promotion and Support of Tourism of North Macedonia; Visit Macedonia Struga city guide; checked 2026-10-02' WHEN 8070009 THEN 'Agency for Promotion and Support of Tourism of North Macedonia; national park and monastery destination sources; checked 2026-10-02' WHEN 8070010 THEN 'Agency for Promotion and Support of Tourism of North Macedonia; national cultural/tourism sources; checked 2026-10-02' WHEN 8070011 THEN 'Agency for Promotion and Support of Tourism of North Macedonia; national destination sources; checked 2026-10-02' WHEN 8070012 THEN 'Agency for Promotion and Support of Tourism of North Macedonia; national destination sources; checked 2026-10-02' END WHERE id BETWEEN 807000001 AND 807000092;
INSERT INTO opening_hours (id,place_id,notes) SELECT id,id,'Exact weekly hours require official/operator/provider refresh; not guessed.' FROM places WHERE id BETWEEN 807000001 AND 807000092;
